export class UserActionBroker{valid(e){return["click","hover","mousedown","mouseup","visibility","keypress","keydown","keyup","focusin","focusout"].includes(e)}fire(e,s,n,o,r=!1){const i=Object.assign({},n,{eventType:s});o.dispatchEvent(new CustomEvent(e,{bubbles:!0,composed:!0,cancelable:!0,detail:i})),r&&(o.innerHTML=`<pre>${JSON.stringify(i,null,2)}</pre>`)}}export const UABroker=new UserActionBroker;